# PharmaFind - writes ALL project files (latest version) into the folder this script is in.
# Run:  powershell -ExecutionPolicy Bypass -File .\add-app-files.ps1
$ErrorActionPreference = "Stop"
$root = Split-Path -Parent $MyInvocation.MyCommand.Path
function W($rel, $b64) {
  $path = Join-Path $root $rel
  $dir = Split-Path -Parent $path
  if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
  [IO.File]::WriteAllBytes($path, [Convert]::FromBase64String($b64))
  Write-Host ("  wrote " + $rel) -ForegroundColor Green
}
Write-Host "PharmaFind: writing project files into $root" -ForegroundColor Cyan
W '.firebaserc' 'ewogICJwcm9qZWN0cyI6IHsKICAgICJkZWZhdWx0IjogInBoYXJtYWZpbmQtMzUyOWMiCiAgfQp9Cg=='
W '.well-known/assetlinks.json' ''
W 'DEPLOY_APK.md' ''
W 'README.md' ''
W 'app.js' ''
W 'firebase-config.js' ''
W 'firebase.json' ''
W 'firestore.rules' ''
W 'icons/apple-touch-icon.png' ''
W 'icons/favicon.png' ''
W 'icons/icon-192.png' ''
W 'icons/icon-512.png' ''
W 'icons/maskable-192.png' ''
W 'icons/maskable-512.png' ''
W 'index.html' ''
W 'manifest.webmanifest' ''
W 'sample-stock.xlsx' ''
W 'seed.html' ''
W 'styles.css' ''
W 'sw.js' ''
Write-Host ""
Write-Host "Done. Now run:  firebase deploy" -ForegroundColor Cyan
